# Output directory
OUTPUT_DIR = "images"

def save_svgs(illus_dict, output_dir):
    os.makedirs(output_dir, exist_ok=True)

    for key, svg_content in illus_dict.items():
        if not svg_content.strip():
            print(f"Skipping empty SVG for key: {key}")
            continue

        file_path = os.path.join(output_dir, f"{key}.svg")

        with open(file_path, "w", encoding="utf-8") as f:
            f.write(svg_content)

        print(f"Saved: {file_path}")

if __name__ == "__main__":
    save_svgs(ILLUS, OUTPUT_DIR)